def fizzbuzz(n):
    result = []
    for i in range(1, n + 1):
        if i % 15 == 0:
            result.append('FizzBuzz')
        elif i % 3 == 0:
            result.append('Fizz')
        elif i % 5 == 0:
            result.append('Buzz')
        else:
            result.append(str(i))
    return result

def parsear_duracion(s):
    s = s.strip()
    total_minutos = 0

    # Separar componentes: horas y minutos
    parts = s.replace('h', ' ').replace('m', ' ').split()

    for part in parts:
        if part.startswith('h'):
            # Extraer valor numérico después de 'h'
            valor = float(part[1:])
            total_minutos += valor * 60
        elif part.startswith('m'):
            # Extraer valor numérico después de 'm'
            valor = float(part[1:])
            total_minutos += valor

    return int(total_minutos)

def aplanar(lista):
    resultado = []
    for elemento in lista:
        if isinstance(elemento, (list, tuple)):
            resultado.extend(aplanar(elemento))
        else:
            resultado.append(elemento)
    return resultado

def buscar(lista, x):
    l = 0
    r = len(lista) - 1
    while l <= r:
        m = (l + r) // 2
        if lista[m] == x:
            return m
        elif lista[m] < x:
            l = m + 1
        else:
            r = m - 1
    return -1

def agrupar_por(items, clave):
    resultado = {}
    for item in items:
        valor = item[clave]
        if valor not in resultado:
            resultado[valor] = []
        resultado[valor].append(item)
    return resultado

def rotar(lista, n):
    if not lista:
        return []
    if n == 0:
        return lista[:]
    n = n % len(lista)
    return lista[-n:] + lista[:-n] if n > 0 else lista[n:] + lista[:n]

def a_romano(n):
    numeros = [
        (1000, 'D'), (900, 'CM'), (500, 'D'), (400, 'CD'),
        (900, 'CM'), (500, 'D'), (400, 'CD'),
        (100, 'C'), (90, 'XC'), (50, 'L'), (40, 'XL'),
        (10, 'X'), (9, 'IX'), (5, 'V'), (4, 'IV')
    ]
    resultado = ''
    temp = n
    while temp > 0:
        for valor, repeticion in numeros:
            if temp >= valor:
                resultado += repeticion
                temp -= valor
                break
    return resultado

def desde_romano(s):
    numeros = {'I': 1, 'V': 5, 'X': 10, 'L': 50, 'C': 100, 'D': 500, 'M': 1000}
    resultado = 0
    i = 0
    while i < len(s):
        valor = numeros.get(s[i], 0)
        if i + 1 < len(s) and numeros.get(s[i+1], 0) > valor:
            resultado += numeros.get(s[i+1], 0) - valor
            i += 2
        else:
            resultado += valor
            i += 1
    return resultado

def mayor_racha(lista):
    if not lista:
        return None

    max_elemento = None
    max_longitud = -1

    i = 0
    while i < len(lista):
        elemento = lista[i]
        longitud = 1
        j = i + 1
        while j < len(lista) and lista[j] == elemento:
            longitud += 1
            j += 1

        if longitud > max_longitud:
            max_longitud = longitud
            max_elemento = elemento

        i = j

    return (max_elemento, max_longitud)

def a_camel(s):
    words = s.split('_')
    return words[0] + ''.join(word[0].upper() + word[1:] for word in words[1:])

def a_snake(s):
    result = []
    for char in s:
        if char.isupper():
            result.append('_')
        result.append(char.lower())
    return ''.join(result).lstrip('_')

def primos(n):
    if n < 2:
        return []
    primos_list = []
    for i in range(2, n + 1):
        is_prime = True
        for j in range(2, int(i**0.5) + 1):
            if i % j == 0:
                is_prime = False
                break
        if is_prime:
            primos_list.append(i)
    return primos_list

def mcd(a, b):
    if a == 0:
        return b
    if b == 0:
        return a
    while b != 0:
        a, b = b, a % b
    return a

def fusionar(intervalos):
    if not intervalos:
        return []

    # Ordenar por inicio, y por fin si los inicios son iguales
    intervalos = sorted(intervalos, key=lambda x: (x[0], x[1]))

    resultado = []

    for inicio, fin in intervalos:
        if resultado and inicio <= resultado[-1][1]:
            # Fusionar con el último intervalo de resultado
            resultado[-1] = (resultado[-1][0], max(resultado[-1][1], fin))
        else:
            resultado.append((inicio, fin))

    return resultado

def es_anagrama(a, b):
    def normalizar(texto):
        return sorted(letra for letra in texto.lower() if letra.isalpha())
    return normalizar(a) == normalizar(b)

def comprimir(s):
    if not s:
        return s

    compresion = []
    count = 1
    for i in range(1, len(s)):
        if s[i] == s[i - 1]:
            count += 1
        else:
            compresion.append(s[i - 1])
            compresion.append(str(count))
            count = 1
    compresion.append(s[-1])
    compresion.append(str(count))
    compresion_str = ''.join(compresion)

    return compresion_str if len(compresion_str) < len(s) else s

def balanceado(texto):
    if not texto:
        return True

    colores = {'(': ')', '{': '}', '}': '}', '[': ']'}
    contador = 0
    for char in texto:
        if char in colores:
            contador += 1
        elif char in '()[]}' and contador > 0:
            if colores.get(char) != texto[contador - 1]:
                return False
            contador -= 1
        elif char in '({[' and contador == 0:
            return False
    return contador == 0

def transpuesta(matriz):
    if not matriz:
        return []
    n = len(matriz)
    resultados = []
    for i in range(len(matriz[0])):
        fila = []
        for j in range(n):
            fila.append(matriz[j][i])
        resultados.append(fila)
    return resultados

def raiz_digital(n):
    while n >= 10:
        suma = 0
        while n > 0:
            suma += n % 10
            n //= 10
        n = suma
    return n

def sin_duplicados(lista):
    resultado = []
    for elemento in lista:
        if elemento not in resultado:
            resultado.append(elemento)
    return resultado

def n_esimo_mayor(lista, n):
    if n <= 0:
        return None
    distinct_values = sorted(set(lista), reverse=True)
    if len(distinct_values) < n:
        return None
    return distinct_values[n - 1]

def formatear_bytes(n):
    if n == 0:
        return '0 B'
    units = ['B', 'KB', 'MB', 'GB']
    unit_index = 0
    while n >= 1024 and unit_index < len(units) - 1:
        n /= 1024
        unit_index += 1
    unit = units[unit_index]
    if unit_index == 0:
        return f"{int(n)} B"
    else:
        parts = []
        whole = int(n)
        fraction = n - whole
        if fraction > 0:
            # Format fraction to one decimal place without trailing zeros beyond one digit
            formatted_fraction = f"{fraction:.1f}".rstrip('0').rstrip('.')
            return f"{whole}.{formatted_fraction} {unit}"
        return f"{whole} {unit}"

def _lotes(lista, tamano):
    if not lista:
        return []
    resultados = []
    inicio = 0
    while lista:
        lote = lista[inicio:inicio + tamano]
        resultados.append(lote)
        inicio += tamano
    return resultados
